    public static void testALineWhollyInsideAKeptSealIsNotBodyText() {
        emon.Port.Cells cand = emon.Port.newCells();
        emon.Port.Cells ow = emon.Port.newCells();
        emon.Port.Cells ol = emon.Port.newCells();
        emon.Port.Cells scr = emon.Port.newCells();
        while (emon.Port.cellsLen(cand) < 16) {
            emon.Port.cellsPush(cand, 0);
        }
        emon.Port.cellsSet(cand, 0, 1);
        emon.Port.cellsSet(cand, 8, 1000);
        emon.Port.cellsSet(cand, 9, 1000);
        emon.Port.cellsSet(cand, 10, 7000);
        emon.Port.cellsSet(cand, 11, 7000);
        emon.Port.cellsSet(cand, 15, -2);
        sptOword(ow, 4000, 4000);
        sptOword(ow, 4000, 4500);
        sptOword(ow, 30000, 4000);
        sptOword(ow, 30000, 30000);
        Evidence.olNew(ol, 1, 3700, 3800, 4300, 4200, 3700, 4200, 4300, 4200, 0, 0, 0, 1);
        Evidence.olNew(ol, 1, 3700, 4300, 30300, 4700, 3700, 4700, 30300, 4700, 0, 0, 1, 2);
        Evidence.olNew(ol, 1, 29700, 29800, 30300, 30200, 29700, 30200, 30300, 30200, 0, 0, 3, 1);
        while (emon.Port.cellsLen(scr) < (Scan.scSelBase() + 8)) {
            emon.Port.cellsPush(scr, 0);
        }
        emon.Port.cellsSet(scr, Scan.scSelBase(), 0);
        emon.Port.cellsSet(scr, Scan.scSelBase() + 1, 1);
        emon.Port.cellsSet(scr, Scan.scSelBase() + 2, 2);
        emon.Testport.assertEq(Sealpx.sxDropLines(scr, 3, ol, ow, cand), 2, "the line in the ring is out; the line that runs from the ring across the page and the line elsewhere stay");
        emon.Testport.assertEq(emon.Port.cellsAt(scr, Scan.scSelBase()), 1, "the first left is the second line");
        emon.Testport.assertEq(emon.Port.cellsAt(scr, Scan.scSelBase() + 1), 2, "then the third");
        emon.Port.cellsSet(cand, 15, -1);
        emon.Port.cellsSet(scr, Scan.scSelBase(), 0);
        emon.Port.cellsSet(scr, Scan.scSelBase() + 1, 1);
        emon.Port.cellsSet(scr, Scan.scSelBase() + 2, 2);
        emon.Testport.assertEq(Sealpx.sxDropLines(scr, 3, ol, ow, cand), 3, "a candidate whose reading was not kept takes nothing out of the body");
    }
